def _sample(shape,profile,generator):
    # Bound temporary arrays without copying any captured row.
    if math.prod(shape)==0:return torch.empty(shape,dtype=torch.float32,device='cpu')
    if profile.get('feature_groups'):
        result=torch.empty(shape,dtype=torch.float32,device='cpu')
        covered=0
        for group in profile['feature_groups']:
            begin,end=group['begin'],min(group['end'],shape[-1])
            if begin>=shape[-1]:continue
            result[...,begin:end]=_sample((*shape[:-1],end-begin),{'cdf':group['cdf'],'quantile_probabilities':profile['quantile_probabilities']},generator)
            covered=end
        if covered!=shape[-1]:raise ValueError('feature profile does not cover input width')
        return result
    result=torch.empty(shape,dtype=torch.float32,device='cpu')
    probabilities=torch.tensor(profile['quantile_probabilities'],dtype=torch.float32,device='cpu')
    table=torch.tensor(profile.get('standardized_cdf',profile['cdf']),dtype=torch.float32,device='cpu')
    flat=result.view(-1)
    for begin in range(0,flat.numel(),1<<20):
        stop=min(begin+(1<<20),flat.numel());u=torch.rand((stop-begin,),generator=generator,dtype=torch.float32,device='cpu')
        lo=torch.searchsorted(probabilities,u,right=True).sub(1).clamp(0,len(probabilities)-2)
        f=(u-probabilities[lo])/(probabilities[lo+1]-probabilities[lo]);flat[begin:stop]=table[lo]*(1-f)+table[lo+1]*f
    if 'row_mean' in profile and len(shape)==2 and len(profile['row_mean'])==shape[0]:
        mean=torch.tensor(profile['row_mean'],dtype=torch.float32,device='cpu')[:,None];std=torch.tensor(profile['row_std'],dtype=torch.float32,device='cpu')[:,None]
        result=(result-result.mean(-1,keepdim=True))/result.std(-1,keepdim=True,unbiased=False).clamp_min(1e-12)*std+mean
    return result


def _layout_tensor(layout,device):
    shape=tuple(layout['shape']);stride=tuple(layout['stride']);offset=layout['storage_offset'];dtype=getattr(torch,layout['dtype'].removeprefix('torch.'))
    if len(shape)!=len(stride) or any(type(n)is not int or n<0 for n in (*shape,*stride,offset)) or math.prod(shape)==0:raise ValueError('invalid captured layout')
    length=offset+1+sum((n-1)*s for n,s in zip(shape,stride))
    if length*dtype.itemsize>3<<30:raise ValueError('layout exceeds observed per-storage memory envelope')
    backing=torch.zeros(length,dtype=dtype,device=device)
    return backing.as_strided(shape,stride,offset)


def yarn_cache(device='cpu',rows=1048576):
    dim=64;base=10000000.;original=262144;factor=4
    i=torch.arange(0,dim,2,dtype=torch.float32,device=device)
    frequencies=base**(i/dim)
    low=max(math.floor(dim*math.log(original/(32*2*math.pi))/(2*math.log(base))),0)
    high=min(math.ceil(dim*math.log(original/(2*math.pi))/(2*math.log(base))),dim-1)
    ramp=((torch.arange(dim//2,dtype=torch.float32,device=device)-low)/(high-low)).clamp(0,1)
    mask=1-ramp;inv=(1/(factor*frequencies))*(1-mask)+(1/frequencies)*mask
    t=torch.arange(rows,dtype=torch.float32,device=device);angles=t[:,None]*inv[None,:]
    scale=1+.1*math.log(factor)
    return torch.cat((angles.cos()*scale,angles.sin()*scale),dim=-1).to(torch.bfloat16)

CACHE_BY_DEVICE={}

def _make_inputs(layout:dict,controls:dict,profile_id:str,seed:int|None=None,dtype:str='bfloat16',device:str='cuda')->dict[str,object]:
    if dtype!='bfloat16' or profile_id not in PROFILES:raise ValueError('invalid captured profile or dtype')
    seed=torch.initial_seed() if seed is None else seed
    if type(seed)is not int or not 0<=seed<2**64:raise ValueError('invalid input seed')
    generator=torch.Generator(device='cpu').manual_seed(seed)
    config=PROFILES[profile_id];expected=config['parameter_layouts']
    if set(layout)!=set(expected) or set(controls)!=set(config['control_names']):raise ValueError('captured ABI field set drift')
    values={};alias_groups={}
    for name,node in layout.items():
        target=_layout_tensor(node,device)
        group=node.get('alias_group')
        if group in alias_groups:raise ValueError('this release supports only independently stored input tensors')
        alias_groups[group]=name
        if device=='meta':values[name]=target;continue
        if name in controls:
            tensor=torch.tensor(controls[name],dtype=target.dtype,device=device)
            if tensor.shape!=target.shape:raise ValueError('control tensor shape drift')
            target.copy_(tensor)
        elif name=='cos_sin_cache':
            if device not in CACHE_BY_DEVICE:CACHE_BY_DEVICE[device]=yarn_cache(device)
            target.copy_(CACHE_BY_DEVICE[device])
        elif node.get('fill')=='zero':pass
        elif name in ('conv_state','conv_states'):
            indices=controls['conv_state_indices' if name=='conv_state' else 'cache_indices'];valid=set(n for n in indices if n>=0);sentinels=[i for i in range(target.shape[0]) if i not in valid][:8]
            for index in list(valid)+sentinels:target[index].copy_(_sample(tuple(target.shape[1:]),config['profiles'][name],generator).to(device=device,dtype=target.dtype))
        else:
            target.copy_(_sample(tuple(target.shape),config['profiles'][name],generator).to(device=device,dtype=target.dtype))
        values[name]=target
    values.update({name:value for name,value in controls.items() if name not in layout})
    return {'positions':values['positions'],'query':values['query'],'key':values['key'],'cos_sin_cache':values['cos_sin_cache']}
